<?php

namespace Didww\Item\SmsTrunkConfiguration;

/**
 * Outbound messages are submitted to DIDWW over HTTP, to the URL in the
 * trunk's meta `host` (SmsTrunk::getHost()).
 */
class HttpOut extends Base
{
    /**
     * Generated by DIDWW and never sent on write.
     */
    public const READ_ONLY_ATTRIBUTES = [
        'auth_name',
        'auth_password',
    ];

    protected const LIST_ATTRIBUTES = ['allowed_ips'];

    protected array $sensitiveAttributes = [
        'auth_name',
        'auth_password',
    ];

    public function getType(): string
    {
        return 'http_out';
    }

    /**
     * URL the status events of submitted messages are sent to.
     */
    public function getCallbackUrl(): ?string
    {
        return $this->attribute('callback_url');
    }

    public function setCallbackUrl(?string $callbackUrl)
    {
        $this->attributes['callback_url'] = $callbackUrl;
    }

    /**
     * @return string[]|null
     */
    public function getAllowedIps(): ?array
    {
        return $this->attribute('allowed_ips');
    }

    /**
     * @param string[]|null $allowedIps addresses messages are accepted from
     */
    public function setAllowedIps(?array $allowedIps)
    {
        $this->attributes['allowed_ips'] = null === $allowedIps ? null : array_values($allowedIps);
    }

    public function getAuthName(): ?string
    {
        return $this->attribute('auth_name');
    }

    public function getAuthPassword(): ?string
    {
        return $this->attribute('auth_password');
    }
}
